echo '#include <iostream>
#include <random>

class CustomHeapManager {
private:
    void* heap_memory;
    size_t heap_size;
    size_t heap_offset;

public:
    CustomHeapManager() : heap_memory(nullptr), heap_size(1024), heap_offset(0) {
        heap_memory = std::malloc(heap_size);
        if (!heap_memory) std::abort();
        std::cout << "CHM constructed, heap = " << heap_memory << std::endl;
    }

    ~CustomHeapManager() {
        std::cout << "CHM destructor, heap = " << heap_memory << std::endl;
        if (heap_memory) {
            std::free(heap_memory);
            heap_memory = nullptr;
        }
        std::cout << "CHM destructor done" << std::endl;
    }

    void* allocate(size_t size) {
        if (!heap_memory) std::abort();
        size_t aligned_size = (size + 15) & ~15;
        if (heap_offset + aligned_size > heap_size) std::abort();
        void* ptr = static_cast<char*>(heap_memory) + heap_offset;
        heap_offset += aligned_size;
        return ptr;
    }

    void deallocate(void* ptr) {
        if (!ptr) return;
        if (!heap_memory) std::abort();
    }
};

static CustomHeapManager* g_custom_heap = nullptr;

void* operator new(std::size_t size) {
    void* ptr;
    if (g_custom_heap) {
        ptr = g_custom_heap->allocate(size);
    } else {
        ptr = std::malloc(size);
    }
    return ptr;
}

void* operator new[](std::size_t size) {
    void* ptr;
    if (g_custom_heap) {
        ptr = g_custom_heap->allocate(size);
    } else {
        ptr = std::malloc(size);
    }
    return ptr;
}

void operator delete(void* ptr) noexcept {
    if (!ptr) return;
    if (g_custom_heap) {
        g_custom_heap->deallocate(ptr);
    } else {
        std::free(ptr);
    }
}

void operator delete[](void* ptr) noexcept {
    if (!ptr) return;
    if (g_custom_heap) {
        g_custom_heap->deallocate(ptr);
    } else {
        std::free(ptr);
    }
}

int main() {
    void* mem = std::malloc(sizeof(CustomHeapManager));
    g_custom_heap = new (mem) CustomHeapManager();
    std::cout << "g_custom_heap = " << g_custom_heap << std::endl;

    {
        std::mt19937 gen(42);
        std::uniform_real_distribution<> dis(-1.0, 1.0);
        std::cout << "Using PRNG" << std::endl;
        double x = dis(gen);
        std::cout << "x = " << x << std::endl;
    }

    std::cout << "After PRNG scope" << std::endl;

    if (g_custom_heap) {
        void* save = g_custom_heap;
        g_custom_heap->~CustomHeapManager();
        g_custom_heap = nullptr;
        std::free(save);
    }

    std::cout << "After shutdown" << std::endl;
    return 0;
}' > /tmp/test2.cpp && g++ -std=c++17 -o /tmp/test2 /tmp/test2.cpp -g -O0 2>&1 && /tmp/test2

